{"command":"python3 - <<'EOF'
# ARP scan the /16: send a TCP SYN-ish nudge to trigger ARP resolution for each host,
# then read /proc/net/arp for live MACs.
import socket, threading, subprocess, time, re

def nudge(ip):
    s = socket.socket()
    s.settimeout(0.3)
    try:
        s.connect((ip, 65000))
    except Exception:
        pass
    finally:
        s.close()

threads = []
for a in range(0, 256):
    if len(threads) > 600:
        for t in threads: t.join()
        threads = []
    t = threading.Thread(target=nudge, args=(f'172.28.{a}.1',))
    t.start(); threads.append(t)
    for b in (2, 100, 200, 254):
        t = threading.Thread(target=nudge, args=(f'172.28.{a}.{b}',))
        t.start(); threads.append(t)
for t in threads: t.join()
time.sleep(0.5)
seen = set()
for line in open('/proc/net/arp'):
    parts = line.split()
    if parts and parts[5] != '00:00:00:00:00:00' and re.match(r'\d+\.\d+\.\d+\.\d+$', parts[0]):
        seen.add((parts[0], parts[5], parts[3]))
for ip, mac, flags in sorted(seen, key=lambda x: tuple(int(o) for o in x[0].split('.'))):
    print(ip, mac, flags)
EOF"}

